const raw = $input.item.json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const fromApp = body.google_chat_payload && typeof body.google_chat_payload === 'object' ? body.google_chat_payload : null;
if (fromApp && (fromApp.text || fromApp.cardsV2)) {
  const text = String(fromApp.text || body.message_vi || body.chat_text || '').trim();
  const payload = {
    ...fromApp,
    text: text ? (text.startsWith('🆕') ? text : '🆕 [APP CRM]\n' + text) : fromApp.text,
  };
  return [{ json: { google_chat_payload: payload } }];
}
const textRaw = String(body.message_vi || body.chat_text || '').trim();
if (!textRaw) return [];
const text = '🆕 [APP CRM]\n' + textRaw;
return [{ json: { google_chat_payload: { text } } }];

const raw = $input.item.json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
let text = String(body.message_vi || body.chat_text || '').trim();
if (!text) {
  const date = body.date || '';
  const tong = body.tongTien != null ? Number(body.tongTien).toLocaleString('vi-VN') : '0';
  const hs = body.tongHocSinhNop != null ? body.tongHocSinhNop : '?';
  text = `📊 BÁO CÁO THU NGÀY ${date}\nTổng HS: ${hs}\nTổng tiền: ${tong} VNĐ`;
}
text = '🆕 [APP CRM]\n' + text;
return [{ json: { google_chat_payload: { text } } }];

const raw = $input.item.json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
let text = String(body.message_vi || body.chat_text || '').trim();
if (!text) {
  const month = body.month || '';
  text = [
    `📆 BÁO CÁO THÁNG ${month}`,
    `NB (chưa thu): ${body.nbMonth ?? 0}`,
    `LPXT: ${body.lpxtMonth ?? 0}`,
    `NE / hoàn thiện: ${body.neMonth ?? 0}`,
    `Top TVV: ${body.topTvvName || '—'} (${body.topTvvCount ?? 0})`,
  ].join('\n');
}
text = '🆕 [APP CRM]\n' + text;
return [{ json: { google_chat_payload: { text } } }];
